          border-radius: 13px;
          background: linear-gradient(145deg, #e9b348, #b97a20);
          display: grid;
          place-items: center;
          color: white;
          font-family: Georgia, serif;
          font-size: 23px;
          font-weight: bold;
          box-shadow: 0 7px 18px rgba(200, 144, 50, 0.22);
        }

        .logo-text strong {
          display: block;
          font-family: Georgia, serif;
          font-size: 22px;
          line-height: 20px;
          color: var(--navy);
        }

        .logo-text span {
          font-size: 9px;
          letter-spacing: 3px;
          color: #687481;
        }

        .nav-links {
          display: flex;
          align-items: center;
          gap: 32px;
        }

        .nav-links button {
          border: 0;
          background: none;
          font-weight: 700;
          color: #24384b;
          cursor: pointer;
          font-size: 14px;
          position: relative;
          padding: 7px 0;
        }

        .nav-links button:after {
          content: "";
          position: absolute;
          bottom: 0;
          left: 50%;
          width: 0;
          height: 2px;
          background: var(--gold);
          transition: 0.3s;
        }

        .nav-links button:hover:after {
          left: 0;
          width: 100%;
        }

        .menu-btn {
          display: none;
          background: none;
          border: 0;
          color: var(--navy);
          cursor: pointer;
        }

        .hero {
          min-height: 760px;
          padding-top: 150px;
          padding-bottom: 80px;
          position: relative;
          background:
            radial-gradient(
              circle at 78% 35%,
              rgba(214, 169, 78, 0.2),
              transparent 32%
            ),
            linear-gradient(110deg, #faf7f0 40%, #f0e5ce);
        }

        .hero:before {
          content: "";
          position: absolute;
          width: 600px;
          height: 600px;
          border: 1px solid rgba(200, 144, 50, 0.18);
          border-radius: 50%;
          right: -200px;
          top: 120px;
        }

        .hero:after {
          content: "";
          position: absolute;
          width: 420px;
          height: 420px;
          border: 1px solid rgba(200, 144, 50, 0.15);
          border-radius: 50%;
          right: -110px;
          top: 210px;
        }

        .hero-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 50px;
          align-items: center;
          position: relative;
          z-index: 2;
        }

        .hero-copy .eyebrow {
          margin-bottom: 22px;
        }

        .hero h1 {
          font-family: Georgia, serif;
          font-size: clamp(48px, 6.2vw, 78px);
          line-height: 0.98;
          color: var(--navy);
          letter-spacing: -2px;
        }

        .hero h1 span {
          color: var(--gold);
        }

        .hero-copy > p {
          max-width: 600px;
          font-size: 18px;
          line-height: 1.75;
          color: #566575;
          margin: 27px 0 32px;
        }

        .hero-actions {
          display: flex;
          gap: 14px;
          flex-wrap: wrap;
        }

        .hero-note {
          display: flex;
          align-items: center;
          gap: 12px;
          margin-top: 30px;
          color: #526274;
          font-size: 13px;
        }

        .hero-note strong {
          color: var(--navy);
        }

        .hero-visual {
          position: relative;
          min-height: 520px;
          display: flex;
          align-items: center;
          justify-content: center;
        }

        .hero-image {
          width: 430px;
          height: 500px;
          object-fit: cover;
          object-position: center;
          border-radius: 220px 220px 30px 30px;
          box-shadow: 25px 30px 70px rgba(29, 45, 58, 0.2);
          border: 8px solid rgba(255, 255, 255, 0.75);
          display: block;
        }

        .hero-badge {
          position: absolute;
          background: white;
          padding: 18px 20px;
          border-radius: 18px;
          box-shadow: 0 15px 40px rgba(20, 40, 55, 0.13);
          display: flex;
          gap: 12px;
          align-items: center;
          z-index: 4;
        }

        .hero-badge.one {
          left: 0;
          top: 100px;
        }

        .hero-badge.two {
          right: 0;
          bottom: 75px;
        }

        .badge-icon {
          width: 43px;
          height: 43px;
          border-radius: 13px;
          background: #fff2d4;
          color: var(--gold);
          display: grid;
          place-items: center;
        }

        .badge-text strong {
          display: block;
          color: var(--navy);
          font-size: 15px;
        }

        .badge-text span {
          font-size: 11px;
          color: #7a8792;
        }

        .mandala {
          position: absolute;
          width: 100px;
          height: 100px;
          border: 2px dashed rgba(200, 144, 50, 0.35);
          border-radius: 50%;
          right: 15px;
          top: 25px;
        }

        .about-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 80px;
          align-items: center;
        }

        .about-image-wrap {
          position: relative;
        }

        .about-image {
          width: 100%;
          height: 540px;
          object-fit: cover;
          object-position: center;
          border-radius: 25px;
          box-shadow: 20px 25px 60px rgba(17, 36, 58, 0.13);
          display: block;
        }

        .about-card {
          position: absolute;
          right: -25px;
          bottom: 30px;
          background: var(--navy);
          color: white;
          padding: 25px;
          border-radius: 20px;
          width: 200px;
          text-align: center;
          box-shadow: 0 20px 45px rgba(9, 35, 56, 0.25);
        }

        .about-card strong {
          display: block;
          font-family: Georgia, serif;
          font-size: 39px;
          color: var(--gold2);
        }

        .about-card span {
          font-size: 12px;
          color: #d5e0e7;
        }

        .about-copy h2 {
          font-family: Georgia, serif;
          font-size: clamp(38px, 5vw, 56px);
          line-height: 1.05;
          color: var(--navy);
          margin-bottom: 22px;
        }

        .about-copy p {
          font-size: 16px;
          line-height: 1.85;
          color: var(--muted);
          margin-bottom: 17px;
        }

        .values {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 15px;
          margin: 28px 0;
        }

        .value {
          padding: 17px;
          border: 1px solid #e8decb;
          border-radius: 15px;
          background: white;
        }

        .value strong {
          display: block;
          margin-bottom: 5px;
          color: var(--navy);
        }

        .value span {
          font-size: 12px;
          color: var(--muted);
        }

        .services-grid {
          display: grid;
          grid-template-columns: repeat(5, 1fr);
          gap: 16px;
        }

        .service {
          background: white;
          border: 1px solid rgba(255, 255, 255, 0.15);
          border-radius: 20px;
          padding: 28px 20px;
          min-height: 340px;
          transition: 0.35s;
          position: relative;
          overflow: hidden;
        }

        .service:before {
          content: "";
          position: absolute;
          width: 100px;
          height: 100px;
          border-radius: 50%;
          background: rgba(200, 144, 50, 0.1);
          right: -40px;
          top: -40px;
        }

        .service:hover {
          transform: translateY(-9px);
          box-shadow: 0 20px 45px rgba(0, 0, 0, 0.2);
        }

        .service-icon {
          width: 58px;
          height: 58px;
          border-radius: 17px;
          display: grid;
          place-items: center;
          background: #fff1cf;
          color: var(--gold);
          margin-bottom: 24px;
        }

        .service h3 {
          font-family: Georgia, serif;
          font-size: 21px;
          margin-bottom: 13px;
        }

        .service p {
          color: #b7c8d3;
          font-size: 13px;
          line-height: 1.7;
          margin-bottom: 20px;
        }

        .tags {
          display: flex;
          flex-wrap: wrap;
          gap: 6px;
        }

        .tag {
          font-size: 10px;
          border: 1px solid #d9e2e8;
          border-radius: 20px;
          padding: 6px 8px;
          color: #60717f;
        }

        .section-dark .tag {
          border-color: #355264;
          color: #d3dfe6;
        }

        .why-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 75px;
          align-items: center;
        }

        .why-copy h2 {
          font-family: Georgia, serif;
          font-size: clamp(38px, 5vw, 56px);
          line-height: 1.08;
          margin-bottom: 20px;
        }

        .why-copy > p {
          line-height: 1.8;
          color: #b9cad4;
          margin-bottom: 25px;
        }

        .why-list {
          display: grid;
          gap: 17px;
        }

        .why-item {
          display: flex;
          gap: 15px;
          align-items: flex-start;
        }

        .why-check {
          width: 35px;
          height: 35px;
          min-width: 35px;
          border-radius: 50%;
          background: rgba(230, 184, 92, 0.15);
          color: var(--gold2);
          display: grid;
          place-items: center;
        }

        .why-item strong {
          display: block;
          margin-bottom: 4px;
        }

        .why-item span {
          font-size: 13px;
          line-height: 1.5;
          color: #a9bdc9;
        }

        .why-photo {
          height: 580px;
          object-fit: cover;
          object-position: center;
          width: 100%;
          border-radius: 30px;
          box-shadow: 0 25px 60px rgba(0, 0, 0, 0.2);
          display: block;
        }

        .tech-wrap {
          display: flex;
          flex-wrap: wrap;
          justify-content: center;
          gap: 12px;
          max-width: 900px;
          margin: auto;
        }

        .tech {
          background: white;
          border: 1px solid #e9e0d0;
          padding: 17px 23px;
          border-radius: 15px;
          display: flex;
          gap: 10px;
          align-items: center;
          transition: 0.25s;
        }

        .tech:hover {
          transform: translateY(-4px);
          border-color: var(--gold);
        }

        .tech-dot {
          width: 9px;
          height: 9px;
          border-radius: 50%;
          background: var(--gold);
        }

        .tech small {
          color: #85909b;
        }

        .process-grid {
          display: grid;
          grid-template-columns: repeat(6, 1fr);
          gap: 14px;
        }

        .process {
          position: relative;
          text-align: center;
        }

        .process:not(:last-child):after {
          content: "→";
          position: absolute;
          right: -13px;
          top: 39px;
          color: var(--gold);
          font-size: 20px;
        }

        .process-num {
          font-family: Georgia, serif;
          font-size: 13px;
          color: var(--gold);
          margin-bottom: 10px;
        }

        .process-icon {
          width: 76px;
          height: 76px;
          border-radius: 50%;
          border: 1px solid #e1c78d;
          background: #fff;
          margin: 0 auto 18px;
          display: grid;
          place-items: center;
          color: var(--gold);
          box-shadow: 0 12px 30px rgba(50, 40, 20, 0.07);
        }

        .process h3 {
          font-family: Georgia, serif;
          margin-bottom: 8px;
        }

        .process p {
          font-size: 12px;
          line-height: 1.6;
          color: var(--muted);
        }

        .stats {
          background: var(--navy);
          color: white;
          padding: 70px 0;
        }

        .stats-grid {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          gap: 20px;
          text-align: center;
        }

        .stat {
          padding: 20px;
          border-right: 1px solid rgba(255, 255, 255, 0.15);
        }

        .stat:last-child {
          border: 0;
        }

        .stat strong {
          font-family: Georgia, serif;
          font-size: 50px;
          color: var(--gold2);
          display: block;
        }

        .stat span {
          font-size: 13px;
          color: #bdcdd6;
        }

        .projects-grid {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          gap: 22px;
        }

        .project {
          background: white;
          border-radius: 22px;
          overflow: hidden;
          box-shadow: 0 10px 35px rgba(25, 43, 60, 0.08);
          transition: 0.35s;
        }

        .project:hover {
          transform: translateY(-8px);
          box-shadow: 0 20px 50px rgba(25, 43, 60, 0.14);
        }

        .project-img {
          width: 100%;
          height: 250px;
          object-fit: cover;
          object-position: center;
          display: block;
        }

        .project-body {
          padding: 25px;
        }

        .project-category {
          font-size: 10px;
          color: var(--gold);
          font-weight: 800;
          letter-spacing: 2px;
          text-transform: uppercase;
        }

        .project h3 {
          font-family: Georgia, serif;
          font-size: 27px;
          margin: 8px 0;
        }

        .project p {
          font-size: 13px;
          line-height: 1.7;
          color: var(--muted);
          margin-bottom: 17px;
        }

        .project-link {
          border: 0;
          background: none;
          color: var(--navy);
          font-weight: 800;
          cursor: pointer;
          display: flex;
          align-items: center;
          gap: 7px;
        }

        .testimonial-grid {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          gap: 22px;
        }

        .testimonial {
          background: white;
          border: 1px solid #eee5d7;
          border-radius: 22px;
          padding: 30px;
          position: relative;
        }

        .stars {
          color: var(--gold);
          display: flex;
          gap: 2px;
          margin-bottom: 20px;
        }

        .testimonial > p {
          font-family: Georgia, serif;
          font-size: 18px;
          line-height: 1.65;
          color: #33495b;
          margin-bottom: 25px;
        }

        .person {
          display: flex;
          align-items: center;
          gap: 13px;
        }

        .person img {
          width: 52px;
          height: 52px;
          border-radius: 50%;
          object-fit: cover;
          display: block;
        }

        .person strong {
          display: block;
          color: var(--navy);
        }

        .person span {
          font-size: 11px;
          color: var(--muted);
        }

        .faq-wrap {
          max-width: 850px;
          margin: auto;
        }

        .faq {
          border-bottom: 1px solid #e1d8ca;
        }

        .faq-question {
          width: 100%;
          padding: 24px 0;
          background: none;
          border: 0;
          display: flex;
          justify-content: space-between;
          align-items: center;
          text-align: left;
          cursor: pointer;
          color: var(--navy);
          font-size: 17px;
          font-weight: 800;
        }

        .faq-answer {
          max-height: 0;
          overflow: hidden;
          transition: 0.35s;
          color: var(--muted);
          line-height: 1.8;
          font-size: 14px;
        }

        .faq.open .faq-answer {
          max-height: 200px;
          padding: 0 40px 22px 0;
        }

        .faq-symbol {
          font-size: 24px;
          color: var(--gold);
        }

        .contact-section {
          background: linear-gradient(135deg, #071f32, #123b52);
          color: white;
        }

        .contact-grid {
          display: grid;
          grid-template-columns: 0.85fr 1.15fr;
          gap: 70px;
          align-items: start;
        }

        .contact-copy h2 {
          font-family: Georgia, serif;
          font-size: clamp(40px, 5vw, 60px);
          line-height: 1.05;
          margin-bottom: 20px;
        }

        .contact-copy > p {
          color: #b8cad5;
          line-height: 1.8;
          margin-bottom: 30px;
        }

        .contact-details {
          display: grid;
          gap: 18px;
        }

        .contact-detail {
          display: flex;
          align-items: center;
          gap: 14px;
        }

        .contact-detail-icon {
          width: 43px;
          height: 43px;
          border-radius: 13px;
          background: rgba(230, 184, 92, 0.13);
          color: var(--gold2);
          display: grid;
          place-items: center;
        }

        .contact-detail strong {
          display: block;
          font-size: 13px;
          margin-bottom: 3px;
        }

        .contact-detail span,
        .contact-detail a {
          font-size: 12px;
          color: #adc0cb;
          text-decoration: none;
        }

        .contact-detail a:hover {
          color: var(--gold2);
        }

        .contact-form {
          background: white;
          color: var(--navy);
          border-radius: 25px;
          padding: 35px;
          box-shadow: 0 25px 60px rgba(0, 0, 0, 0.2);
        }

        .form-title {
          font-family: Georgia, serif;
          font-size: 30px;
          margin-bottom: 22px;
        }

        .form-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 15px;
        }

        .field {
          margin-bottom: 15px;
        }

        .field.full {
          grid-column: 1 / -1;
        }

        .field label {
          display: block;
          font-size: 11px;
          font-weight: 800;
          margin-bottom: 7px;
          color: #556575;
        }

        .field input,
        .field textarea,
        .field select {
          width: 100%;
          border: 1px solid #e1e5e8;
          border-radius: 12px;
          padding: 14px;
          font-family: inherit;
          outline: none;
          background: #fbfcfd;
          transition: 0.2s;
        }

        .field textarea {
          min-height: 120px;
          resize: vertical;
        }

        .field input:focus,
        .field textarea:focus,
        .field select:focus {
          border-color: var(--gold);
          box-shadow: 0 0 0 3px rgba(200, 144, 50, 0.1);
        }

        .form-button {
          width: 100%;
        }

        .footer {
          background: #061b2b;
          color: #b7c7d0;
          padding: 60px 0 25px;
        }

        .footer-grid {
          display: grid;
          grid-template-columns: 1.5fr 1fr 1fr 1fr;
          gap: 40px;
          padding-bottom: 45px;
        }

        .footer .logo-text strong {
          color: white;
        }

        .footer-description {
          font-size: 13px;
          line-height: 1.8;
          max-width: 320px;
          margin-top: 18px;
        }

        .footer h4 {
          color: white;
          margin-bottom: 18px;
          font-size: 14px;
        }

        .footer-links {
          display: grid;
          gap: 11px;
        }

        .footer-links button {
          background: none;
          border: 0;
          color: #aebec8;
          text-align: left;
          cursor: pointer;
          font-size: 12px;
        }

        .footer-links button:hover {
          color: var(--gold2);
        }

        .footer-bottom {
          border-top: 1px solid rgba(255, 255, 255, 0.1);
          padding-top: 23px;
          display: flex;
          justify-content: space-between;
          gap: 20px;
          font-size: 11px;
        }

        .socials {
          display: flex;
          gap: 8px;
        }

        .social {
          width: 34px;
          height: 34px;
          border: 1px solid #385263;
          border-radius: 50%;
          display: grid;
          place-items: center;
          color: #c4d2d9;
          text-decoration: none;
          transition: 0.25s;
        }

        .social:hover {
          background: var(--gold);
          color: var(--navy);
          border-color: var(--gold);
        }

        .traditional {
          position: absolute;
          opacity: 0.08;
          pointer-events: none;
          font-family: Georgia, serif;
          color: var(--gold);
          font-size: 100px;
        }

        .t1 {
          left: -25px;
          top: 30px;
        }

        .t2 {
          right: -25px;
          bottom: 30px;
        }

        @media (max-width: 1050px) {
          .services-grid {
            grid-template-columns: repeat(3, 1fr);
          }

          .process-grid {
            grid-template-columns: repeat(3, 1fr);
            gap: 35px;
          }

          .process:not(:last-child):after {
            display: none;
          }

          .nav-links {
            gap: 20px;
          }
        }

        @media (max-width: 850px) {
          .nav-links {
            position: absolute;
            top: 78px;
            left: 0;
            right: 0;
            background: rgba(250, 247, 240, 0.98);
            padding: 25px;
            display: none;
            flex-direction: column;
            align-items: stretch;
            gap: 5px;
            box-shadow: 0 20px 30px rgba(0, 0, 0, 0.08);
          }

          .nav-links.open {
            display: flex;
          }

          .nav-links button {
            text-align: center;
            padding: 13px;
          }

          .navbar .btn {
            display: none;
          }

          .menu-btn {
            display: block;
          }

          .hero {
            padding-top: 120px;
          }

          .hero-grid,
          .about-grid,
          .why-grid,
          .contact-grid {
            grid-template-columns: 1fr;
            gap: 45px;
          }

          .hero-visual {
            min-height: 470px;
          }

          .hero-image {
            height: 450px;
            width: 370px;
          }

          .hero-badge.one {
            left: 0;
          }

          .hero-badge.two {
            right: 0;
          }

          .about-image {
            height: 430px;
          }

          .why-photo {
            height: 450px;
          }

          .projects-grid,
          .testimonial-grid {
            grid-template-columns: 1fr;
          }

          .stats-grid {
            grid-template-columns: 1fr 1fr;
          }

          .stat {
            border-right: 0;
            border-bottom: 1px solid rgba(255, 255, 255, 0.15);
          }

          .footer-grid {
            grid-template-columns: 1fr 1fr;
          }
        }

        @media (max-width: 600px) {
          .section {
            padding: 75px 0;
          }

          .hero h1 {
            font-size: 48px;
          }

          .hero-copy > p {
            font-size: 15px;
          }

          .hero-visual {
            min-height: 390px;
          }

          .hero-image {
            height: 390px;
            width: 285px;
          }

          .hero-badge {
            padding: 12px;
          }

          .hero-badge.one {
            left: -5px;
            top: 55px;
          }

          .hero-badge.two {
            right: -5px;
            bottom: 30px;
          }

          .badge-icon {
            width: 36px;
            height: 36px;
          }

          .badge-text strong {
            font-size: 12px;
          }

          .badge-text span {
            font-size: 9px;
          }

          .services-grid {
            grid-template-columns: 1fr;
          }

          .service {
            min-height: auto;
          }

