import React, { useEffect, useState } from "react";

export default function Home() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [activeFaq, setActiveFaq] = useState(0);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", handleScroll);

    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollTo = (id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);

    if (el) {
      el.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }
  };

  const Icon = ({ type, size = 26 }) => {
    const icons = {
      code: (
        <>
          <path d="M9 18 3 12l6-6" />
          <path d="m15 6 6 6-6 6" />
          <path d="m14 4-4 16" />
        </>
      ),

      design: (
        <>
          <rect x="3" y="3" width="18" height="18" rx="3" />
          <path d="M8 8h8M8 12h5M8 16h8" />
        </>
      ),

      marketing: (
        <>
          <path d="M3 11v2" />
          <path d="M6 9v6" />
          <path d="M9 7v10" />
          <path d="M12 5v14" />
          <path d="M15 8v8" />
          <path d="M18 10v4" />
          <path d="M21 12h.01" />
        </>
      ),

      mobile: (
        <>
          <rect x="6" y="2" width="12" height="20" rx="3" />
          <path d="M10 18h4" />
        </>
      ),

      cloud: (
        <path d="M17.5 19H9a6 6 0 1 1 1.3-11.86A7 7 0 0 1 23 12a4 4 0 0 1-5.5 7Z" />
      ),

      shield: (
        <>
          <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z" />
          <path d="m9 12 2 2 4-5" />
        </>
      ),

      rocket: (
        <>
          <path d="M4.5 16.5c-1.5 1.5-2 4-2 4s2.5-.5 4-2l2-2-2-2-2 2Z" />
          <path d="m14 5 5 5" />
          <path d="M13 4c3-2 7-2 8-1-1 1 0 5-1 7l-7 7-5-5 7-8Z" />
          <circle cx="16" cy="8" r="1" />
        </>
      ),

      target: (
        <>
          <circle cx="12" cy="12" r="9" />
          <circle cx="12" cy="12" r="5" />
          <circle cx="12" cy="12" r="1" />
        </>
      ),

      users: (
        <>
          <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" />
          <circle cx="9" cy="7" r="4" />
          <path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" />
        </>
      ),

      check: <path d="m5 12 4 4L19 6" />,

      arrow: (
        <>
          <path d="M5 12h14" />
          <path d="m13 6 6 6-6 6" />
        </>
      ),

      star: (
        <path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9L12 3Z" />
      ),

      phone: (
        <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.78.62 2.63a2 2 0 0 1-.45 2.11L8 9.73a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.85.29 1.73.5 2.63.62A2 2 0 0 1 22 16.92Z" />
      ),

      mail: (
        <>
          <rect x="3" y="5" width="18" height="14" rx="2" />
          <path d="m3 7 9 6 9-6" />
        </>
      ),

      location: (
        <>
          <path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z" />
          <circle cx="12" cy="10" r="2.5" />
        </>
      ),

      menu: <path d="M4 6h16M4 12h16M4 18h16" />,

      close: (
        <>
          <path d="M6 6l12 12" />
          <path d="M18 6 6 18" />
        </>
      ),

      spark: (
        <>
          <path d="m12 3 1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5L12 3Z" />
          <path d="m19 16 .7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7L19 16Z" />
        </>
      ),

      database: (
        <>
          <ellipse cx="12" cy="5" rx="8" ry="3" />
          <path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5" />
          <path d="M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7" />
        </>
      ),

      layers: (
        <>
          <path d="m12 2 9 5-9 5-9-5 9-5Z" />
          <path d="m3 12 9 5 9-5" />
          <path d="m3 17 9 5 9-5" />
        </>
      ),

      headphones: (
        <>
          <path d="M3 18v-6a9 9 0 0 1 18 0v6" />
          <path d="M21 19a2 2 0 0 1-2 2h-1v-7h3v5ZM3 19a2 2 0 0 0 2 2h1v-7H3v5Z" />
        </>
      ),
    };

    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {icons[type] || icons.spark}
      </svg>
    );
  };

  const services = [
    {
      icon: "code",
      title: "Web Development",
      text: "High-performance websites and web platforms engineered for speed, accessibility, scalability and measurable business growth.",
      tags: ["React", "Next.js", "Node.js"],
    },
    {
      icon: "design",
      title: "UI/UX Design",
      text: "Human-centered digital experiences combining research, visual systems, interaction design and conversion-focused interfaces.",
      tags: ["Figma", "Design Systems", "Prototyping"],
    },
    {
      icon: "marketing",
      title: "Digital Marketing",
      text: "Data-led marketing strategies that increase visibility, attract qualified audiences and turn attention into sustainable growth.",
      tags: ["SEO", "Social Media", "Analytics"],
    },
    {
      icon: "mobile",
      title: "Mobile Development",
      text: "Modern Android and iOS applications with intuitive interfaces, secure architecture and reliable performance.",
      tags: ["Android", "iOS", "Cross Platform"],
    },
    {
      icon: "cloud",
      title: "Cloud Development",
      text: "Secure cloud-native solutions designed for resilience, automation, cost efficiency and effortless scaling.",
      tags: ["AWS", "Azure", "DevOps"],
    },
  ];

  const technologies = [
    ["React", "Frontend"],
    ["Next.js", "Frontend"],
    ["Node.js", "Backend"],
    ["Python", "Backend"],
    ["Java", "Backend"],
    ["Flutter", "Mobile"],
    ["MongoDB", "Database"],
    ["PostgreSQL", "Database"],
    ["AWS", "Cloud"],
    ["Docker", "DevOps"],
    ["Figma", "Design"],
    ["GitHub", "Development"],
  ];

  const process = [
    [
      "01",
      "Discover",
      "We understand your goals, audience, challenges and opportunities before writing a single line of code.",
      "target",
    ],
    [
      "02",
      "Strategize",
      "We convert business requirements into a clear digital roadmap with measurable priorities.",
      "layers",
    ],
    [
      "03",
      "Design",
      "We create intuitive interfaces and experiences that feel natural, premium and purposeful.",
      "design",
    ],
    [
      "04",
      "Build",
      "Our engineers transform the approved experience into secure, scalable and high-quality products.",
      "code",
    ],
    [
      "05",
      "Launch",
      "We test, optimize, deploy and monitor your solution for a confident launch.",
      "rocket",
    ],
    [
      "06",
      "Grow",
      "We continue improving your product using data, feedback, experiments and technology.",
      "spark",
    ],
  ];

  const projects = [
    {
      title: "FinEdge",
      category: "FinTech Platform",
      text: "A modern financial management experience designed around clarity, trust and frictionless digital journeys.",
      image:
        "https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=85",
    },
    {
      title: "Medivista",
      category: "Healthcare Experience",
      text: "A patient-focused digital ecosystem that makes appointments, information and communication easier.",
      image:
        "https://images.unsplash.com/photo-1559757148-5c350d0d3c56?auto=format&fit=crop&w=1200&q=85",
    },
    {
      title: "UrbanCart",
      category: "E-Commerce",
      text: "A conversion-focused shopping experience built for speed, discovery and effortless checkout.",
      image:
